import type { ReactNode } from 'react'

export type IntegrationStatus = 'connected' | 'available' | 'beta' | 'soon'
export type IntegrationHealth = 'healthy' | 'degraded' | 'error'

/** A day of a connection's sync history, as the history strip draws it. */
export interface IntegrationSyncDay {
  /** An ISO date ("2026-09-12"). */
  date: string
  /** The share of that day's syncs that succeeded, 0 to 1; `null` when none ran. */
  uptime: number | null
  note?: string
}

/** What is known about a live connection. */
export interface IntegrationConnection {
  /** The account or workspace on the other side ("acme-org"). */
  account: string
  connectedBy: string
  /** When it was connected, a timestamp in milliseconds. */
  connectedAt: number
  /** When it last synced, a timestamp in milliseconds. */
  lastSync: number
  health: IntegrationHealth
  /** One line on the health, for a degraded or failing connection. */
  healthNote?: string
  /** The last weeks of syncs, oldest first. */
  history?: IntegrationSyncDay[]
}

/** An integration in the hub. */
export interface Integration {
  id: string
  name: string
  category: string
  /** One line for the card. */
  description: string
  /** A glyph drawn in a 24×24 viewBox (the children of an `<svg>`), filled with the text color. The demo's are the brands' own marks from Simple Icons (CC0; the marks are their owners' trademarks). */
  mark?: ReactNode
  /** Your own logo node (an `<img>`), in place of `mark`. */
  logo?: ReactNode
  status: IntegrationStatus
  /** The longer paragraph in the detail; default: `description`. */
  about?: string
  /** Shown with a Popular tag. */
  popular?: boolean
  /** What it does once connected, as short phrases. */
  features?: string[]
  /** What it asks to read or change. */
  scopes?: string[]
  /** More words the search finds it by. */
  keywords?: string[]
  docsHref?: string
  /** Present when `status` is `connected`. */
  connection?: IntegrationConnection
}

/** The demo's clock: `now` defaults to this so the relative times don't drift. */
export const NOW = Date.UTC(2026, 8, 29, 9, 0)
const HOUR = 3_600_000
const DAY = 24 * HOUR

const history = (failures: Record<number, number | null> = {}): IntegrationSyncDay[] =>
  Array.from({ length: 30 }, (_, i) => {
    const date = new Date(NOW - (29 - i) * DAY).toISOString().slice(0, 10)
    return { date, uptime: i in failures ? failures[i]! : 1 }
  })

